# app.py
import textwrap
from pathlib import Path
from tempfile import NamedTemporaryFile
from typing import List, Tuple, Optional

import viktor as vkt
from viktor.errors import UserError

import ifcopenshell
import ifcopenshell.api
import ifcopenshell.guid
import ifcopenshell.util.element


def _extract_vkt_file(upload) -> vkt.File:
    """MultiFileField can return a list of file-wrappers (with .file) or File objects.

    This helper makes the rest of the code robust against both.
    """
    if upload is None:
        raise UserError("No file was provided.")
    if isinstance(upload, vkt.File):
        return upload
    if hasattr(upload, "file"):
        return upload.file
    raise UserError("Unsupported uploaded-file object returned by MultiFileField.")


def _save_to_temp_ifc(vkt_file: vkt.File) -> Path:
    """Persist the uploaded IFC to a temp file so IfcOpenShell can read it."""
    with NamedTemporaryFile(delete=False, suffix=".ifc") as tmp:
        tmp.write(vkt_file.getvalue())
        return Path(tmp.name)


def _load_ifc_from_vkt_file(vkt_file: vkt.File) -> ifcopenshell.file:
    path = _save_to_temp_ifc(vkt_file)
    try:
        return ifcopenshell.open(str(path))
    except Exception as e:
        raise UserError(f"Failed to open IFC file '{path.name}'. Details: {e}")


def _get_file_label(upload, idx: int) -> str:
    # Best-effort label for UI: try common attributes, fall back to index.
    for attr in ("name", "filename", "file_name", "title"):
        if hasattr(upload, attr) and getattr(upload, attr):
            return str(getattr(upload, attr))
    return f"IFC_{idx:02d}"


def _merge_ifc_files(
    uploads: list,
    rename_projects_to_filename: bool,
    regenerate_global_ids: bool,
) -> Tuple[Path, List[str]]:
    """Merge IFC files into a single STEP file.

    Strategy:
    - For each input file, import its IfcProject(s) as an independent sub-model.
    - This preserves each file's internal spatial structure, relationships, property sets,
      and geometry (best-effort) without needing fragile remapping.

    Note:
    - The resulting federated IFC may contain multiple IfcProject entities (one per input file).
      This is a practical federation approach for coordination/visual checking.
    """
    if not uploads:
        raise UserError("Upload at least one IFC file.")

    labels: List[str] = []
    models: List[ifcopenshell.file] = []

    for i, upload in enumerate(uploads, start=1):
        vkt_file = _extract_vkt_file(upload)
        label = _get_file_label(upload, i)
        labels.append(label)
        models.append(_load_ifc_from_vkt_file(vkt_file))

    schemas = {m.schema for m in models}
    if len(schemas) != 1:
        raise UserError(
            "All uploaded IFC files must use the same schema to merge. "
            f"Found: {', '.join(sorted(schemas))}"
        )

    target_schema = models[0].schema
    federated = ifcopenshell.api.run("project.create_file", version=target_schema)

    for label, src in zip(labels, models):
        projects = src.by_type("IfcProject")
        if not projects:
            raise UserError("One of the uploaded IFC files does not contain an IfcProject.")

        for src_project in projects:
            new_project = federated.add(src_project)  # deep-copy the project graph
            if rename_projects_to_filename and new_project is not None:
                try:
                    new_project.Name = label
                except Exception:
                    pass

    if regenerate_global_ids:
        for root in federated.by_type("IfcRoot"):
            try:
                root.GlobalId = ifcopenshell.guid.new()
            except Exception:
                # Some roots may have locked/invalid GlobalId; ignore.
                pass

    with NamedTemporaryFile(delete=False, suffix=".ifc") as tmp_out:
        out_path = Path(tmp_out.name)

    federated.write(str(out_path))
    return out_path, labels


def _psets_to_datagroup(psets: dict) -> vkt.DataGroup:
    pset_items: List[vkt.DataItem] = []
    for pset_name, props in sorted(psets.items(), key=lambda x: str(x[0])):
        if not isinstance(props, dict):
            continue
        sub_items = [
            vkt.DataItem(str(k), "" if v is None else str(v))
            for k, v in sorted(props.items(), key=lambda x: str(x[0]))
        ]
        # DataItem with subgroup renders as a collapsible group.
        pset_items.append(vkt.DataItem(str(pset_name), "", subgroup=vkt.DataGroup(*sub_items)))
    if not pset_items:
        return vkt.DataGroup(vkt.DataItem("Properties", "No property sets found."))
    return vkt.DataGroup(*pset_items)


class Parametrization(vkt.Parametrization):
    page_input = vkt.Page("1. Upload", views=[])
    page_input.sec_intro = vkt.Section("Application")
    page_input.sec_intro.text = vkt.Text(
        textwrap.dedent(
            """\
            # IFC Merger (Federated Model)

            Upload multiple IFC models (e.g. Architectural, Structural, MEP) and generate a **federated IFC**.

            What this app does:
            - Imports each uploaded IFC as a sub-model (best-effort preservation of geometry + data)
            - Visualizes the merged result in a 3D IFC viewer
            - Allows downloading the federated IFC for coordination workflows

            Notes:
            - To maximize robustness, federation is performed by importing each file's `IfcProject` graph.
              The resulting federated IFC may contain multiple `IfcProject` objects (one per input file).
            - Ensure all uploaded IFCs use the **same schema** (e.g. IFC4).
            """
        )
    )

    page_input.sec_upload = vkt.Section("Upload IFC files")
    page_input.sec_upload.ifc_files = vkt.MultiFileField("IFC files", file_types=[".ifc"])

    page_input.sec_settings = vkt.Section("Merge settings")
    page_input.sec_settings.rename_projects = vkt.BooleanField(
        "Rename imported IfcProject.Name to the file name", default=True
    )
    page_input.sec_settings.regenerate_guids = vkt.BooleanField(
        "Regenerate GlobalId for all IfcRoot entities (avoid ID clashes)", default=False
    )

    page_results = vkt.Page("2. Federated model", views=["merged_ifc_view"])
    page_results.sec_tools = vkt.Section("Inspect & download")
    page_results.sec_tools.geometry = vkt.GeometrySelectField("Select element (optional)")
    page_results.sec_tools.text = vkt.Text(
        textwrap.dedent(
            """\
            ## Tips
            - Use the selection tool to click an element in the viewer and inspect its property sets.
            - Use the download button (top right) to export the federated IFC.
            """
        )
    )


class Controller(vkt.Controller):
    label = "IFC Merger (Federated Model)"
    parametrization = Parametrization(width=45)

    def _build_federated_ifc(self, params) -> Tuple[Path, List[str]]:
        uploads = params.page_input.sec_upload.ifc_files or []
        return _merge_ifc_files(
            uploads=uploads,
            rename_projects_to_filename=bool(params.page_input.sec_settings.rename_projects),
            regenerate_global_ids=bool(params.page_input.sec_settings.regenerate_guids),
        )

    @vkt.IFCAndDataView("Federated IFC (3D)", duration_guess=10, x_axis_to_right=True)
    def merged_ifc_view(self, params, **kwargs):
        out_path, labels = self._build_federated_ifc(params)

        # Load for inspection / selection lookups
        model = ifcopenshell.open(str(out_path))

        selected = params.page_results.sec_tools.geometry
        if selected:
            try:
                element = model.by_id(int(selected))
            except Exception:
                element = None

            if element is None:
                data = vkt.DataGroup(vkt.DataItem("Selection", "Could not resolve selection."))
            else:
                psets = ifcopenshell.util.element.get_psets(element)
                info = vkt.DataGroup(
                    vkt.DataItem("IFC class", element.is_a()),
                    vkt.DataItem("Name", getattr(element, "Name", "") or ""),
                    vkt.DataItem("GlobalId", getattr(element, "GlobalId", "") or ""),
                    vkt.DataItem("STEP id", str(element.id())),
                )
                data = vkt.DataGroup(
                    vkt.DataItem("Element", "", subgroup=info),
                    vkt.DataItem("Property sets", "", subgroup=_psets_to_datagroup(psets)),
                )
        else:
            # Summary panel when nothing is selected
            counts = {
                "IfcProject": len(model.by_type("IfcProject")),
                "IfcSite": len(model.by_type("IfcSite")),
                "IfcBuilding": len(model.by_type("IfcBuilding")),
                "IfcBuildingStorey": len(model.by_type("IfcBuildingStorey")),
                "IfcProduct": len(model.by_type("IfcProduct")),
                "IfcElement": len(model.by_type("IfcElement")),
                "IfcSpace": len(model.by_type("IfcSpace")),
            }
            common = [
                "IfcWall",
                "IfcSlab",
                "IfcBeam",
                "IfcColumn",
                "IfcDoor",
                "IfcWindow",
                "IfcDuctSegment",
                "IfcPipeSegment",
                "IfcCableCarrierSegment",
            ]
            for cls in common:
                try:
                    n = len(model.by_type(cls))
                except Exception:
                    n = 0
                if n:
                    counts[cls] = n

            counts_group = vkt.DataGroup(*[vkt.DataItem(k, v) for k, v in counts.items()])
            files_group = vkt.DataGroup(*[vkt.DataItem(f"File {i}", name) for i, name in enumerate(labels, start=1)])
            data = vkt.DataGroup(
                vkt.DataItem("Schema", model.schema),
                vkt.DataItem("Input files", "", subgroup=files_group),
                vkt.DataItem("Entity counts", "", subgroup=counts_group),
            )

        return vkt.IFCAndDataResult(ifc=vkt.File.from_path(out_path), data=data)

    @vkt.DownloadButton("Download federated IFC")
    def download_federated_ifc(self, params, **kwargs):
        out_path, _labels = self._build_federated_ifc(params)
        return vkt.DownloadResult(file=vkt.File.from_path(out_path), file_name="federated.ifc")
